//! ➗️ Equation-owned expression entities, the parent-owned graph and point cloud, and the derived composed child references.
use semio_framework_value::{ValueError,ValueRefusalKind};
use crate::standards::v1::subsets::any::schema::snapshot::{EquationSnapshot,EquationNode,EquationNodeLabel,EquationNodeKind,EquationExprSnapshot};
use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::{SqliteDatabase,SqliteRow,SqliteSnapshotControl,SqliteSnapshotPhase,SnapshotEncoding,validate_sqlite_database_schema,artifact::{Projection,Cell,Reconstruction,NativeEncodingBound,ordered_row_refs}}};
use std::collections::{BTreeMap,BTreeSet};
fn words(value:u64)->[Cell<'static>;2]{[Cell::Integer((value>>32)as i64),Cell::Integer((value&0xffffffff)as i64)]}
fn word(row:&SqliteRow,index:usize)->Result<u64,ValueError>{let high=u32::try_from(row.integer(index)?).map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?;let low=u32::try_from(row.integer(index+1)?).map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?;Ok((u64::from(high)<<32)|u64::from(low))}
fn children(node:&EquationNode)->impl Iterator<Item=&EquationNode>+Clone{let(slice,first,second):(&[EquationNode],Option<&EquationNode>,Option<&EquationNode>)=match&node.kind{EquationNodeKind::Add{terms}=>(terms,None,None),EquationNodeKind::Mul{factors}=>(factors,None,None),EquationNodeKind::Pow{base,exponent}=>(&[],Some(base),Some(exponent)),_=>(&[],None,None)};slice.iter().chain(first).chain(second)}
fn child_count(node:&EquationNode)->usize{match&node.kind{EquationNodeKind::Add{terms}=>terms.len(),EquationNodeKind::Mul{factors}=>factors.len(),EquationNodeKind::Pow{..}=>2,_=>0}}

fn kind(node:&EquationNode)->&'static str{match node.kind{EquationNodeKind::Integer{..}=>"integer",EquationNodeKind::Rational{..}=>"rational",EquationNodeKind::Symbol{..}=>"symbol",EquationNodeKind::Add{..}=>"add",EquationNodeKind::Mul{..}=>"mul",EquationNodeKind::Pow{..}=>"pow"}}
pub(super) fn retire_node(node:EquationNode){let mut pending=vec![node];while let Some(node)=pending.pop(){match node.kind{EquationNodeKind::Add{terms}=>pending.extend(terms),EquationNodeKind::Mul{factors}=>pending.extend(factors),EquationNodeKind::Pow{base,exponent}=>{pending.push(*base);pending.push(*exponent);},_=>{}}}}
struct OwnedNodes(BTreeMap<i64,EquationNode>);
impl Drop for OwnedNodes{fn drop(&mut self){while let Some((_,node))=self.0.pop_first(){retire_node(node);}}}
fn ordinal(value:usize)->Result<i64,ValueError>{i64::try_from(value).map_err(|e|ValueError::new(ValueRefusalKind::WorkLimit,e.to_string()))}
fn graph_rows(snapshot:&EquationSnapshot)->usize{1+snapshot.graph.nodes.len()+snapshot.graph.edges.len()+snapshot.geometry.points.len()}
fn graph_bytes(snapshot:&EquationSnapshot)->Result<usize,ValueError>{let graph=&snapshot.graph;let mut bytes=checked_add(32+graph.algorithm.len(),graph.algorithm_seed.as_ref().map_or(0,String::len))?;for node in&graph.nodes{bytes=checked_add(bytes,checked_add(48+node.id.len(),node.label.len())?)?;}for edge in&graph.edges{bytes=checked_add(bytes,checked_add(checked_add(32+edge.id.len(),edge.source.len())?,edge.target.len())?)?;}checked_add(bytes,snapshot.geometry.points.len().checked_mul(48).ok_or_else(||ValueError::new(ValueRefusalKind::OwnershipLimit,"Equation byte count overflow"))?)}
fn sqlite_rows(snapshot:&EquationSnapshot)->Result<usize,ValueError>{let mut rows=checked_add(5,graph_rows(snapshot))?;let mut pending=vec![&snapshot.equation.expr];while let Some(node)=pending.pop(){let edges=if matches!(node.kind,EquationNodeKind::Add{..}|EquationNodeKind::Mul{..}){child_count(node)}else{0};rows=checked_add(rows,checked_add(2,edges)?)?;pending.extend(children(node));}Ok(rows)}
fn checked_add(value:usize,count:usize)->Result<usize,ValueError>{value.checked_add(count).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"Equation resource count overflow"))}
fn take<'a>(maps:&[BTreeMap<i64,&'a SqliteRow>],used:&mut BTreeSet<(usize,i64)>,table:usize,id:i64)->Result<&'a SqliteRow,ValueError>{if !used.insert((table,id)){return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Equation entity has repeated owner"))}maps[table].get(&id).copied().ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"Equation entity is missing"))}
type Edges<'a>=BTreeMap<i64,BTreeMap<usize,&'a SqliteRow>>;
fn ordered(table:usize,id:i64,edges:&[Edges<'_>;2],maps:&[BTreeMap<i64,&SqliteRow>],used:&mut BTreeSet<(usize,i64)>)->Result<Vec<i64>,ValueError>{let Some(rows)=edges[table-12].get(&id)else{return Ok(vec![])};let mut result=Vec::with_capacity(rows.len());for(index,(&ordinal,row))in rows.iter().enumerate(){if index!=ordinal{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Equation noncontiguous ordinal"))}result.push(take(maps,used,table,row.rowid)?.integer(3)?);}Ok(result)}

fn same(a:&EquationNode,b:&EquationNode,control:&mut SqliteSnapshotControl<'_>)->Result<(),ValueError>{let mut pending=vec![(a,b)];let mut count=0;while let Some((a,b))=pending.pop(){if a.label!=b.label||kind(a)!=kind(b){return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Equation node identity differs"))}match(&a.kind,&b.kind){(EquationNodeKind::Integer{lexeme:a},EquationNodeKind::Integer{lexeme:b})if a!=b=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Equation lexical identity differs")),(EquationNodeKind::Rational{numer:a,denom:x},EquationNodeKind::Rational{numer:b,denom:y})if a!=b||x!=y=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Equation lexical identity differs")),(EquationNodeKind::Symbol{name:a},EquationNodeKind::Symbol{name:b})if a!=b=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Equation symbol identity differs")),_=>{}}let ac=children(a);let bc=children(b);if child_count(a)!=child_count(b){return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Equation children identity differs"))}pending.extend(ac.into_iter().zip(bc));count+=1;if count%256==0{control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,count,0)?;}}Ok(())}
impl ArtifactSqliteSnapshot for EquationSnapshot{
 fn decode_sqlite_snapshot_native(payload:&store::io::IoPayload,control:&mut store::sqlite_snapshot::SqliteSnapshotControl<'_>,native_control: &mut semio_framework_os_kernel::NativeSnapshotDecodeOwner<'_, '_>)->Result<Self,ValueError>{
  control.checkpoint(SqliteSnapshotPhase::DecodeNative,0,0)?;if Self::SQLITE_SCHEMA.len()>control.limits().max_schema_bytes{return Err(ValueError::new(ValueRefusalKind::OwnershipLimit,"Equation authored schema byte limit exceeded"))}
  crate::standards::v1::subsets::any::io::binary::snapshot::decode_sqlite_native(payload,control,native_control)
 }
 fn encode_sqlite_snapshot_native(&self,encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>,native_owner:&mut semio_framework_os_kernel::NativeSnapshotEncodeOwner<'_, '_>)->Result<store::io::IoPayload,ValueError>{control.checkpoint(SqliteSnapshotPhase::EncodeNative,0,0)?;if Self::SQLITE_SCHEMA.len()>control.limits().max_schema_bytes{return Err(ValueError::new(ValueRefusalKind::OwnershipLimit,"Equation authored schema byte limit exceeded"))}control.check_rows(sqlite_rows(self)?)?;crate::standards::v1::subsets::any::io::binary::snapshot::encode_sqlite_native(self,encoding,control,native_owner)}
 const SQLITE_SCHEMA:&'static str=include_str!("🗄️.sql");
 fn retire_sqlite_snapshot(self){retire_node(self.equation.expr);}
 fn preflight_sqlite_snapshot_encoding(&self,_encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<(),ValueError>{let mut bound=NativeEncodingBound::new(control)?;bound.add(8192)?;bound.check_rows(graph_rows(self))?;bound.add(graph_bytes(self)?)?;bound.repeated(graph_rows(self),16)?;for(child_id,target)in[(&self.notation.child_id,&self.notation.target),(&self.results.child_id,&self.results.target),(&self.computed.child_id,&self.computed.target)]{for value in[child_id,&target.artifact_id,&target.dialect.artifact_kind,&target.dialect.standard,&target.dialect.subset]{bound.repeated(value.len(),6)?;}}let mut pending=vec![&self.equation.expr];let mut count=0;while let Some(node)=pending.pop(){count+=1;bound.check_rows(checked_add(count,pending.len())?)?;bound.add(512)?;let children=children(node);bound.check_rows(checked_add(checked_add(count,pending.len())?,child_count(node))?)?;bound.repeated(child_count(node),96)?;match&node.kind{EquationNodeKind::Integer{lexeme}=>bound.repeated(lexeme.len(),6)?,EquationNodeKind::Rational{numer,denom}=>{bound.repeated(numer.len(),6)?;bound.repeated(denom.len(),6)?;},EquationNodeKind::Symbol{name}=>bound.repeated(name.len(),6)?,_=>{}}pending.extend(children);}bound.finish()}
 fn to_sqlite_database(&self,control:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,ValueError>{let mut p=Projection::new(Self::SQLITE_SCHEMA,control)?;let mut rows=checked_add(5,graph_rows(self))?;let mut bytes=checked_add(96,graph_bytes(self)?)?;for(child_id,target)in[(&self.notation.child_id,&self.notation.target),(&self.results.child_id,&self.results.target),(&self.computed.child_id,&self.computed.target)]{for value in[child_id,&target.artifact_id,&target.dialect.artifact_kind,&target.dialect.standard,&target.dialect.subset]{bytes=checked_add(bytes,value.len())?;}}p.check_rows(checked_add(rows,2)?)?;p.check_value_bytes(bytes)?;let mut nodes=vec![&self.equation.expr];let mut index=0;while index<nodes.len(){if index%256==0{p.checkpoint()?;}let node=nodes[index];let kids=children(node);let edges=if matches!(node.kind,EquationNodeKind::Add{..}|EquationNodeKind::Mul{..}){child_count(node)}else{0};rows=checked_add(rows,checked_add(2,edges)?)?;bytes=checked_add(bytes,40+kind(node).len())?;bytes=checked_add(bytes,edges.checked_mul(32).ok_or_else(||ValueError::new(ValueRefusalKind::OwnershipLimit,"Equation byte count overflow"))?)?;match&node.kind{EquationNodeKind::Integer{lexeme}=>bytes=checked_add(bytes,lexeme.len())?,EquationNodeKind::Rational{numer,denom}=>bytes=checked_add(checked_add(bytes,numer.len())?,denom.len())?,EquationNodeKind::Symbol{name}=>bytes=checked_add(bytes,name.len())?,EquationNodeKind::Pow{..}=>bytes=checked_add(bytes,16)?,_=>{}}p.check_value_bytes(bytes)?;p.check_rows(checked_add(rows,(nodes.len()-index-1+child_count(node)).checked_mul(2).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"Equation row count overflow"))?)?)?;nodes.extend(kids);index+=1;}
 p.insert_key("equation_document",1,&[])?;for(name,child_id,target)in[("equation_notation_child",&self.notation.child_id,&self.notation.target),("equation_results_child",&self.results.child_id,&self.results.target),("equation_computed_child",&self.computed.child_id,&self.computed.target)]{p.insert_key(name,1,&[Cell::Integer(1),Cell::Text(child_id),Cell::Text(&target.artifact_id),Cell::Text(&target.dialect.artifact_kind),Cell::Text(&target.dialect.standard),Cell::Text(&target.dialect.subset)])?;}let[high,low]=words(self.equation.next_label);p.insert_key("equation_expression",1,&[Cell::Integer(1),Cell::Integer(1),high,low])?;let mut next=2i64;for(index,node)in nodes.into_iter().enumerate(){let id=i64::try_from(index+1).map_err(|e|ValueError::new(ValueRefusalKind::WorkLimit,e.to_string()))?;let[high,low]=words(node.label.0);p.insert_key("equation_node",id,&[Cell::Integer(1),high,low,Cell::Text(kind(node))])?;match&node.kind{EquationNodeKind::Integer{lexeme}=>p.insert_key("equation_integer",id,&[Cell::Text(lexeme)])?,EquationNodeKind::Rational{numer,denom}=>p.insert_key("equation_rational",id,&[Cell::Text(numer),Cell::Text(denom)])?,EquationNodeKind::Symbol{name}=>p.insert_key("equation_symbol",id,&[Cell::Text(name)])?,EquationNodeKind::Pow{..}=>{p.insert_key("equation_pow",id,&[Cell::Integer(next),Cell::Integer(next.checked_add(1).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"Equation identity overflow"))?)])?;next=next.checked_add(2).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"Equation identity overflow"))?;},EquationNodeKind::Add{terms}|EquationNodeKind::Mul{factors:terms}=>{let(table,edge)=if matches!(node.kind,EquationNodeKind::Add{..}){("equation_add","equation_add_term")}else{("equation_mul","equation_mul_factor")};p.insert_key(table,id,&[])?;for ordinal in 0..terms.len(){p.insert(edge,&[Cell::Integer(id),Cell::Integer(i64::try_from(ordinal).map_err(|e|ValueError::new(ValueRefusalKind::WorkLimit,e.to_string()))?),Cell::Integer(next)])?;next=next.checked_add(1).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"Equation identity overflow"))?;}}}}
 let graph=&self.graph;p.insert_key("equation_graph",1,&[Cell::Integer(1),Cell::Integer(i64::from(graph.directed)),Cell::Text(&graph.algorithm),graph.algorithm_seed.as_deref().map_or(Cell::Null,Cell::Text)])?;for(index,node)in graph.nodes.iter().enumerate(){if index%256==0{p.checkpoint()?;}p.insert("equation_graph_node",&[Cell::Integer(1),Cell::Integer(ordinal(index)?),Cell::Text(&node.id),Cell::Text(&node.label),Cell::Real(node.x),Cell::Real(node.y)])?;}for(index,edge)in graph.edges.iter().enumerate(){if index%256==0{p.checkpoint()?;}p.insert("equation_graph_edge",&[Cell::Integer(1),Cell::Integer(ordinal(index)?),Cell::Text(&edge.id),Cell::Text(&edge.source),Cell::Text(&edge.target)])?;}for(index,point)in self.geometry.points.iter().enumerate(){if index%256==0{p.checkpoint()?;}p.insert("equation_point",&[Cell::Integer(1),Cell::Integer(ordinal(index)?),Cell::Real(point.x),Cell::Real(point.y)])?;}
 p.finish()}
 fn from_sqlite_database(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->Result<Self,ValueError>{control.check_database(database,SqliteSnapshotPhase::ReconstructSnapshot)?;validate_sqlite_database_schema(database,Self::SQLITE_SCHEMA,control.limits())?;let names=[("equation_document",1),("equation_notation_child",7),("equation_results_child",7),("equation_computed_child",7),("equation_expression",5),("equation_node",5),("equation_integer",2),("equation_rational",3),("equation_symbol",2),("equation_add",1),("equation_mul",1),("equation_pow",3),("equation_add_term",4),("equation_mul_factor",4),("equation_graph",5),("equation_graph_node",7),("equation_graph_edge",6),("equation_point",5)];let mut maps=Vec::with_capacity(names.len());let mut total=0;for(name,width)in names{let table=database.table(name)?;let mut map=BTreeMap::new();for row in&table.rows{if row.values.len()!=width||row.integer(0)?!=row.rowid||map.insert(row.rowid,row).is_some(){return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Equation row identity differs"))}total+=1;if total%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,total,0)?;}}maps.push(map);}let mut used=BTreeSet::new();for table in 0..5{if maps[table].len()!=1{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Equation fixed entity differs"))}}let document_id=*maps[0].first_key_value().ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"Equation document missing"))?.0;take(&maps,&mut used,0,document_id)?;
 let mut child=|table:usize|->Result<(String,semio_framework_artifact_reference::ArtifactRef),ValueError>{let id=*maps[table].first_key_value().ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"Equation child missing"))?.0;let row=take(&maps,&mut used,table,id)?;if row.integer(1)?!=document_id{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Equation child parent differs"))}let mut r=Reconstruction::new(control)?;Ok((r.text(row.text(2)?)?,semio_framework_artifact_reference::ArtifactRef{artifact_id:r.text(row.text(3)?)?,dialect:semio_framework_artifact_reference::ArtifactDialect{artifact_kind:r.text(row.text(4)?)?,standard:r.text(row.text(5)?)?,subset:r.text(row.text(6)?)?}}))};let(id,target)=child(1)?;let notation=store::ArtifactChild::new(id,target);let(id,target)=child(2)?;let results=store::ArtifactChild::new(id,target);let(id,target)=child(3)?;let computed=store::ArtifactChild::new(id,target);if maps[14].len()!=1{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Equation graph entity differs"))}let graph_id=*maps[14].first_key_value().ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"Equation graph missing"))?.0;let graph_row=take(&maps,&mut used,14,graph_id)?;if graph_row.integer(1)?!=document_id{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Equation graph parent differs"))}let directed=match graph_row.integer(2)?{0=>false,1=>true,_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Equation graph direction differs"))};let mut r=Reconstruction::new(control)?;r.scalar()?;let algorithm=r.text(graph_row.text(3)?)?;let algorithm_seed=graph_row.optional_text(4)?.map(|seed|r.text(seed)).transpose()?;let mut graph=crate::EquationGraph{directed,nodes:Vec::new(),edges:Vec::new(),algorithm,algorithm_seed};for row in ordered_row_refs(database.table("equation_graph_node")?,2,control)?{take(&maps,&mut used,15,row.rowid)?;if row.integer(1)?!=graph_id{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Equation graph node owner differs"))}let mut r=Reconstruction::new(control)?;r.scalar()?;r.scalar()?;graph.nodes.push(crate::EquationNode{id:r.text(row.text(3)?)?,label:r.text(row.text(4)?)?,x:row.real(5)?,y:row.real(6)?});}for row in ordered_row_refs(database.table("equation_graph_edge")?,2,control)?{take(&maps,&mut used,16,row.rowid)?;if row.integer(1)?!=graph_id{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Equation graph edge owner differs"))}let mut r=Reconstruction::new(control)?;graph.edges.push(crate::EquationEdge{id:r.text(row.text(3)?)?,source:r.text(row.text(4)?)?,target:r.text(row.text(5)?)?});}let mut geometry=crate::EquationGeometry{points:Vec::new()};for row in ordered_row_refs(database.table("equation_point")?,2,control)?{take(&maps,&mut used,17,row.rowid)?;if row.integer(1)?!=document_id{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Equation point owner differs"))}let mut r=Reconstruction::new(control)?;r.scalar()?;r.scalar()?;geometry.points.push(crate::EquationPoint{x:row.real(3)?,y:row.real(4)?});}let expression_id=*maps[4].first_key_value().ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"Equation expression missing"))?.0;let expression=take(&maps,&mut used,4,expression_id)?;if expression.integer(1)?!=document_id{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Equation expression parent differs"))}let root=expression.integer(2)?;let next_label=word(expression,3)?;let mut edges:[Edges<'_>;2]=[BTreeMap::new(),BTreeMap::new()];for table in[12,13]{for(index,row)in maps[table].values().enumerate(){let owner=row.integer(1)?;let ordinal=usize::try_from(row.integer(2)?).map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?;if edges[table-12].entry(owner).or_default().insert(ordinal,row).is_some(){return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Equation repeated ordinal"))}if index%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,index,maps[table].len())?;}}}let mut pending=vec![root];let mut plans=Vec::new();while let Some(id)=pending.pop(){let node=take(&maps,&mut used,5,id)?;if node.integer(1)?!=expression_id{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Equation node expression differs"))}let kind=node.text(4)?;let table=match kind{"integer"=>6,"rational"=>7,"symbol"=>8,"add"=>9,"mul"=>10,"pow"=>11,_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Equation node variant differs"))};let row=take(&maps,&mut used,table,id)?;let kids=match kind{"add"=>ordered(12,id,&edges,&maps,&mut used)?,"mul"=>ordered(13,id,&edges,&maps,&mut used)?,"pow"=>vec![row.integer(1)?,row.integer(2)?],_=>vec![]};pending.extend(kids.iter().copied());plans.push((id,word(node,2)?,kind,row,kids));if plans.len()%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,plans.len(),0)?;}}
 if used.len()!=total{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Equation has unowned entity rows"))}let mut values=OwnedNodes(BTreeMap::new());let total=plans.len();for(index,(id,label,kind,row,kids))in plans.into_iter().rev().enumerate(){let mut r=Reconstruction::new(control)?;r.scalar()?;r.scalar()?;let mut children=kids.into_iter().map(|id|values.0.remove(&id).ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"Equation child topology differs"))).collect::<Result<Vec<_>,_>>()?;let kind=match kind{"integer"=>EquationNodeKind::Integer{lexeme:r.text(row.text(1)?)?},"rational"=>EquationNodeKind::Rational{numer:r.text(row.text(1)?)?,denom:r.text(row.text(2)?)?},"symbol"=>EquationNodeKind::Symbol{name:r.text(row.text(1)?)?},"add"=>EquationNodeKind::Add{terms:children},"mul"=>EquationNodeKind::Mul{factors:children},"pow"=>{let exponent=children.pop().ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"Equation exponent missing"))?;let base=children.pop().ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"Equation base missing"))?;EquationNodeKind::Pow{base:Box::new(base),exponent:Box::new(exponent)}},_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Equation node variant differs"))};values.0.insert(id,EquationNode{label:EquationNodeLabel(label),kind});if index%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,index,total)?;}}if values.0.len()!=1{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Equation root differs"))}control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,total,total)?;let expr=values.0.remove(&root).ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"Equation root missing"))?;Ok(Self{graph,geometry,notation,results,computed,equation:EquationExprSnapshot{expr,next_label}})}
 fn validate_sqlite_snapshot_subset(&self,dialect:&semio_framework_artifact_reference::ArtifactDialect,database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->store::io_schema::IoResult<()>{control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,0).map_err(store::io_schema::IoError::from_value_error)?;if dialect.artifact_kind!="s.mathematical.equation"||dialect.standard!="1"||dialect.subset!="*"{return Err(store::io_schema::IoError::from_value_error(ValueError::new(ValueRefusalKind::UnsupportedOwner,"Equation does not own this semantic subset")))}let restored=Self::from_sqlite_database(database,control).map_err(store::io_schema::IoError::from_value_error)?;let outcome=if self.graph!=restored.graph||self.geometry!=restored.geometry||self.notation!=restored.notation||self.results!=restored.results||self.computed!=restored.computed||self.equation.next_label!=restored.equation.next_label{Err(ValueError::new(ValueRefusalKind::InvalidValue,"Equation fixed identity differs"))}else{same(&self.equation.expr,&restored.equation.expr,control)};Self::retire_sqlite_snapshot(restored);outcome.map_err(store::io_schema::IoError::from_value_error)?;Ok(store::io_schema::IoOutcome{value:(),diagnostics:vec![]})}
}

